import type { CopilotAction, CopilotIntent, Role } from '@hr/shared'

/**
 * What people say, and where it should go.
 *
 * Written by hand, in both languages, with the role attached to every line.
 * The alternative was tried: two thousand sentences generated by recombining
 * sixteen templates. It produced 1,899 unique strings, 39% of them about two
 * actions because those templates had one more slot to permute, no Arabic at
 * all, one broken sentence per prefix collision, and — the part that made it
 * unusable here — `allowed: true` on 1,889 of 1,899 rows.
 *
 * That last field is why a generated set cannot measure this assistant. Whether
 * something is allowed is not a property of the sentence. "Delete this vacancy"
 * is a normal instruction from HR and a refusal from an employee, and the same
 * words must produce both. A corpus without the asker in it is measuring half
 * the system and calling it the whole.
 *
 * So every case carries a role, and a third of them expect REFUSED — not
 * off-topic trivia, which is easy, but real HR requests from people who may not
 * make them, which is the refusal that matters.
 *
 * The labels are the system's own names, checked against the registries by
 * `corpus.check.ts`. A case cannot name an action that does not exist, and an
 * action with no case is reported as uncovered rather than quietly untested.
 */

export interface Case {
  role: Role
  text: string
  /** An action name, an intent name, or REFUSED when the role may not. */
  expect: CopilotAction | CopilotIntent | 'REFUSED'
}

const ar = (role: Role, text: string, expect: Case['expect']): Case => ({ role, text, expect })
const en = ar

